// ─── src/components/ContactModal.js ───
import React, { useState, useRef } from 'react';
import styled from 'styled-components';
import axios from 'axios';

const Overlay = styled.div`
  position: fixed;
  top: 0; left: 0;
  width: 100vw; height: 100vh;
  background: #111;
  display: flex;
  justify-content: center;
  /* 최상단 약간 띄우고 내부 스크롤 허용 */
  align-items: flex-start;
  padding-top: 20px;
  z-index: 999;
  overflow-y: auto;  
  -webkit-overflow-scrolling: touch;
`;

const Modal = styled.div`
  position: relative;
  width: 80%;
  max-width: 1200px;
  /* 전체 화면 높이의 90% 까지만 차지하도록, 넘칠 땐 스크롤 */
  padding: 40px;
  box-sizing: border-box;
  color: #fff;

  @media (max-width: 768px) {
    width: 90%;
    padding: 20px;
  }
`;

// 로고 래퍼 (invert 처리)
const LogoWrapper = styled.div`
  text-align: center;
  margin-bottom: 20px;

  img {
    width: 100%;
    max-width: 350px;
    /* 검정 로고를 흰색으로 반전 */
    filter: invert(1);
  }
`;

// 로고 바로 아래에 나올 이메일·주소
const LogoInfo = styled.div`
  text-align: center;
  margin-bottom: 30px;

  p {
    margin: 4px 0;
    font-size: clamp(16px, 3vw, 20px);
    font-weight: 400;
    color: #fff;
  }
`;

const InfoText = styled.div`
  text-align: center;
  margin: 40px 0;
  line-height: 1.5;
  color: #fff;

  @media (max-width: 420px) {
    margin: 60px 0;
  }

  p {
    margin: 8px 0;
    font-size: clamp(16px, 4vw, 24px);
    font-weight: 500;
  }
  p:last-child {
    margin-top: 24px;
    font-size: clamp(18px, 5vw, 28px);
    font-weight: 700;
  }
`;

const Subtitle = styled.p`
  margin: 10px 0 40px;
  text-align: center;
  font-size: 35px;
  font-weight: 600;

  @media (max-width: 768px) {
    font-size: 16px;
    margin-bottom: 20px;
  }
`;

const Form = styled.form`
  width: 100%;
`;

const Columns = styled.div`
  display: flex;
  gap: 20px;
  @media (max-width: 768px) {
    flex-direction: column;
    gap: 30px;
  }
`;

const Left = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 15px;
`;

const Right = styled.div`
  flex: 1;
`;

const StyledInput = styled.input`
  width: 100%;
  padding: 15px;
  box-sizing: border-box;
  border: none;
  outline: none;
  font-size: 16px;
  background: #222;
  color: #fff;
  &::placeholder { color: #999; }
  @media (max-width: 480px) {
    padding: 12px;
    font-size: 14px;
  }
`;

const FileInputWrapper = styled.div`
  position: relative;
  width: 100%;
`;

const FileDisplayInput = styled.input`
  width: 100%;
  padding: 15px 130px 15px 15px;
  box-sizing: border-box;
  border: 1px solid #ccc;
  border-radius: 4px;
  background: #fff;
  color: #333;
  font-size: 16px;
  &::placeholder { color: #888; }
  &:focus { outline: none; border-color: #999; }
`;

const SearchButton = styled.button`
  position: absolute;
  top: 50%;
  right: 10px;
  transform: translateY(-50%);
  padding: 8px 16px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background: #fff;
  color: #333;
  font-size: 14px;
  cursor: pointer;
  &:hover { background: #f5f5f5; }
`;

const HiddenFileInput = styled.input`
  display: none;
`;

const StyledTextarea = styled.textarea`
  width: 100%;
  height: 260px;
  padding: 15px;
  box-sizing: border-box;
  border: none;
  outline: none;
  resize: none;
  font-size: 16px;
  background: #222;
  color: #fff;
  &::placeholder { color: #999; }
  @media (max-width: 768px) {
    height: 180px;
    font-size: 14px;
    padding: 12px;
  }
`;

const SendButton = styled.button`
  display: block;
  margin: 40px auto 0;
  padding: 15px 60px;
  background: transparent;
  border: 1px solid #fff;
  font-size: 20px;
  cursor: pointer;
  color: #fff;
  @media (max-width: 768px) {
    width: 100%;
    padding: 12px 0;
    font-size: 18px;
  }
  @media (max-width: 480px) {
    font-size: 16px;
    margin-top: 20px;
  }
`;

export default function ContactModal({ onClose = () => {} }) {
  const [companyEmail, setCompanyEmail] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [file, setFile] = useState(null);
  const [fileName, setFileName] = useState('');
  const [message, setMessage] = useState('');
  const fileInputRef = useRef(null);

  const handleFileClick = () => fileInputRef.current.click();
  const handleFileChange = (e) => {
    const f = e.target.files[0];
    if (f) {
      setFile(f);
      setFileName(f.name);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!companyEmail) {
      alert('Company Email is required.');
      return;
    }

    const formData = new FormData();
    formData.append('companyEmail', companyEmail);
    formData.append('companyName', companyName);
    formData.append('url', '');
    if (file) formData.append('attachment', file);
    formData.append('message', message);

    try {
      await axios.post(
        'https://port-0-ychat-lzgmwhc4d9883c97.sel4.cloudtype.app/send-email',
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );
      alert('Your request has been sent!');
      window.location.href = 'https://yogico.kr';
    } catch (err) {
      console.error('전송 오류:', err);
      alert('Send failed: ' + (err.response?.data?.error || err.message));
    }
  };

  return (
    <Overlay>
      <Modal>
        <LogoWrapper>
          <img
            src="https://yogibo.kr/yogico/img/icon/Signature03.png"
            alt="Yogi Corporation Logo"
          />
        </LogoWrapper>

        <LogoInfo>
          <p>contact@yogico.kr</p>
          <p style={{fontSize:'18px'}}>#201 125, Bongeunsa-ro, Gangnam-gu, Seoul, Republic of Korea</p>
        </LogoInfo>

        <InfoText>
          <p>Yes, this is the correct site of <strong>Yogi Corporation Inc.</strong></p>
          <p>A renewal is in progress and will launch next month.</p>
          <p>Thank you for the patience!</p>
          <p>Please feel free to drop us a line!</p>
        </InfoText>

        <Subtitle>CONTACT</Subtitle>
        <Form onSubmit={handleSubmit}>
          <Columns>
            <Left>
              <StyledInput
                type="email"
                placeholder="Company Email *"
                value={companyEmail}
                onChange={(e) => setCompanyEmail(e.target.value)}
                required
              />
              <StyledInput
                type="text"
                placeholder="Company Name"
                value={companyName}
                onChange={(e) => setCompanyName(e.target.value)}
              />
              <FileInputWrapper>
                <FileDisplayInput
                  readOnly
                  placeholder="Attach a file"
                  value={fileName}
                  onClick={handleFileClick}
                />
                <SearchButton type="button" onClick={handleFileClick}>
                  Choose File
                </SearchButton>
                <HiddenFileInput
                  type="file"
                  ref={fileInputRef}
                  onChange={handleFileChange}
                />
              </FileInputWrapper>
            </Left>
            <Right>
              <StyledTextarea
                placeholder="Describe your collaboration request"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
              />
            </Right>
          </Columns>
          <SendButton type="submit">SEND</SendButton>
        </Form>
      </Modal>
    </Overlay>
  );
}
